corrected_code:
class TenantSMTPSettings(BaseSettings):
    smtp_host: str
    smtp_port: int
    smtp_user: str
    smtp_pass: SecretStr
    use_tls: bool = True

@app.get("/api/v1/tenants/{tenant_id}/mail-config")
def retrieve_smtp_settings(
    tenant_id: int,
    vault: SecretVault = Depends(get_secret_vault),
    current_user: User = Depends(get_current_user)
):
    if current_user.tenant_id != tenant_id or not current_user.is_admin:
        raise HTTPException(status_code=403, detail="Forbidden: Insufficient privileges for requested tenant")
    raw_creds = vault.get_tenant_credentials(tenant_id=tenant_id, service="smtp")
    if not raw_creds:
        raise HTTPException(status_code=404, detail="SMTP credentials not found")
    smtp_config = TenantSMTPSettings(**raw_creds)
    return {
        "host": smtp_config.smtp_host,
        "port": smtp_config.smtp_port,
        "username": smtp_config.smtp_user,
        "password": smtp_config.smtp_pass.get_secret_value()
    }
